"><?php foreach($artists as $a):?><option value="<?=$a['id']?>" <?=$a['id']==$r['artist_id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label><label>Title<input name="title" value="<?=e($r['title'])?>"></label><label>Date<input type="date" name="release_date" value="<?=e($r['release_date'])?>"></label><label>Catalogue<input name="catalogue_number" value="<?=e($r['catalogue_number'])?>"></label><label>Replace artwork<input type="file" name="artwork" accept="image/jpeg,image/png,image/webp"></label><label class="check"><input type="checkbox" name="featured" <?=$r['is_featured']?'checked':''?>> Featured</label><label class="wide">Description<textarea name="description"><?=e($r['description'])?></textarea></label><div class="form-actions wide"><button class="button" name="action" value="release_update">Save</button><button class="button danger" name="action" value="release_delete" onclick="return confirm('Delete this optional release?')">Delete</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"></form></details><?php endforeach;?></div></section><?php endif;?>

