<?php if($section==='reviews'):$reviewRows=$pdo->query("SELECT s.*,u.display_name,u.email,g.name genre_name FROM artist_submissions s JOIN users u ON u.id=s.user_id LEFT JOIN genres g ON g.id=s.genre_id WHERE s.status='pending' ORDER BY s.created_at ASC,s.id ASC")->fetchAll();?><div class="section-title"><div><span class="kicker">CATALOGUE INBOX</span><h1>Track Reviews</h1></div><span><?=count($reviewRows)?> pending</span></div><p class="panel muted">Artist uploads are held privately until an administrator checks the rights, metadata and audio. Approval converts the submission into a normal track.</p><section class="admin-review-list"><?php if(!$reviewRows):?><div class="panel account-empty"><h3>No pending submissions</h3><p>Approved and rejected submissions remain recorded in the database.</p></div><?php endif;?><?php foreach($reviewRows as $r):$creditNames=parse_artist_credit_names((string)$r['artist_name']);$submissionArtistIds=[];$linkSt=$pdo->prepare('SELECT artist_id FROM artist_submission_artists WHERE submission_id=? ORDER BY sort_order,artist_id');$linkSt->execute([(int)$r['id']]);$submissionArtistIds=array_map('intval',$linkSt->fetchAll(PDO::FETCH_COLUMN));$existingCreditCount=0;foreach($artists as $candidate){if(artist_credit_name_matches((string)$candidate['name'],$creditNames))$existingCreditCount++;}$allCreditsExist=count($creditNames)>0&&$existingCreditCount===count($creditNames);?><details class="panel admin-review-card"><summary><span><strong><?=e($r['artist_name'])?> — <?=e($r['title'])?></strong><small><?=e($r['mix_name']?:'No remix name')?> · <?=e($r['genre_name']?:'No genre')?> · <?=e($r['bpm']?:'—')?> BPM · submitted by <?=e($r['display_name'])?></small></span><span><?=e($r['created_at'])?></span><span class="button secondary tiny review-button">Review</span></summary><div class="admin-review-body"><div class="admin-review-facts"><div><span>Artist(s)</span><strong><?=e($r['artist_name'])?></strong></div><div><span>Track</span><strong><?=e($r['title'])?></strong></div><div><span>Remix</span><strong><?=e($r['mix_name']?:'—')?></strong></div><div><span>Genre</span><strong><?=e($r['genre_name']?:'—')?></strong></div><div><span>BPM</span><strong><?=e($r['bpm']?:'—')?></strong></div><div><span>Submitter</span><strong><?=e($r['email'])?></strong></div></div><button type="button" class="button secondary review-preview-button" data-preview="<?=e(url('private-audio.php?submission='.rawurlencode((string)$r['id']).'&preview=1'))?>" data-title="<?=e($r['title'])?>" data-artist="<?=e($r['artist_name'])?>" data-art="<?=e(url('assets/images/empty-art.svg'))?>"><span data-play-icon>▶</span> Play review preview</button><form method="post" class="admin-review-form"><input type="hidden" name="submission_id" value="<?=$r['id']?>"><label class="review-artists-field">Artists (select all collaborators)<select name="artist_ids[]" multiple size="4"><?php foreach($artists as $a):?><option value="<?=$a['id']?>" <?=($submissionArtistIds?in_array((int)$a['id'],$submissionArtistIds,true):artist_credit_name_matches((string)$a['name'],$creditNames))?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select><small class="muted">Detected credits: <?=e(implode(' · ',$creditNames)?:'none')?>. The first selected artist is primary.</small></label><label class="check review-create-artist"><input type="checkbox" name="create_artist" <?=$allCreditsExist?'disabled':''?>> <?=$allCreditsExist?'All detected artists already exist':'Create missing detected artist(s)'?></label><label class="review-title-field">Track title<input name="title" value="<?=e($r['title'])?>" required></label><label class="review-remix-field">Remix name<input name="mix_name" value="<?=e($r['mix_name']??'')?>"></label><label class="review-genre-field">Genre<select name="genre_id"><option value="">No genre</option><?php foreach($genres as $g):?><option value="<?=$g['id']?>" <?=$g['id']==$r['genre_id']?'selected':''?>><?=e($g['name'])?></option><?php endforeach;?></select></label><label class="review-bpm-field">BPM<input name="bpm" type="number" min="40" max="300" value="<?=e($r['bpm']??'')?>"></label><label class="review-price-field">Price (£)<input name="price" value="1.49" required></label><label class="review-release-field">Release date<input name="release_date" type="date" value="<?=date('Y-m-d')?>"></label><input type="hidden" name="action" value="submission_approve"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-actions wide"><button class="button" name="action" value="submission_approve">Approve and create track</button></div></form><form method="post" class="admin-review-reject"><input type="hidden" name="submission_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="submission_reject"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Rejection note<textarea name="review_note" maxlength="500" placeholder="Explain what needs to be corrected"></textarea></label><button class="button danger" onclick="return confirm('Reject this submission?')">Reject submission</button></form></div></details><?php endforeach;?></section><?php endif;?>

<?php if($section==='artist_access'):$artistUsers=$pdo->query('SELECT id,display_name,email,is_artist,email_verified_at,disabled_at,banned_at FROM users WHERE is_admin=0 ORDER BY display_name,email')->fetchAll();?><div class="section-title"><div><span class="kicker">SUBMISSIONS</span><h1>Artist Access</h1></div><span>Enable uploads for trusted users</span></div><p class="panel muted">An artist can submit audio and metadata for review. This does not publish anything automatically; an administrator must approve each submission.</p><section class="panel admin-list-panel"><div class="admin-section-head"><h2>Customer artist permissions</h2><span><?=count($artistUsers)?> users</span></div><div class="admin-table user-admin-table"><div class="admin-row user-admin-head"><strong>Name</strong><strong>Email</strong><strong>Verified</strong><strong>Status</strong><strong>Artist access</strong><strong>Action</strong></div><?php foreach($artistUsers as $x):$artistAction=$x['is_artist']?'user_artist_disable':'user_artist_enable';?><div class="admin-row"><span><strong><?=e($x['display_name'])?></strong></span><span><?=e($x['email'])?></span><span><?=$x['email_verified_at']?'<span class="badge">Yes</span>':'<span class="muted">No</span>'?></span><span><?=!empty($x['banned_at'])?'<span class="badge danger-badge">Banned</span>':(!empty($x['disabled_at'])?'<span class="badge muted">Disabled</span>':'<span class="badge">Active</span>')?></span><span><?=$x['is_artist']?'<span class="badge">Artist enabled</span>':'<span class="muted">Customer</span>'?></span><span><form method="post" data-no-async><input type="hidden" name="user_id" value="<?=$x['id']?>"><input type="hidden" name="action" value="<?=e($artistAction)?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button type="submit" class="button <?=$x['is_artist']?'secondary':'tiny'?> tiny"><?=$x['is_artist']?'Remove artist access':'Enable artist access'?></button></form></span></div><?php endforeach;?></div></section><?php endif;?>

<?php if($section==='users'):$allUsers=$pdo->query('SELECT id,display_name,email,email_verified_at,last_login_at,is_admin,is_artist,disabled_at,banned_at,ban_reason,created_at FROM users ORDER BY created_at DESC,id DESC')->fetchAll();?><div class="section-title"><div><span class="kicker">CUSTOMERS</span><h1>Users</h1></div><span><?=count($allUsers)?> registered</span></div><section class="panel admin-list-panel"><div class="admin-section-head"><h2>System users</h2><span>Name · email · validation · last login · status</span></div><div class="admin-table user-admin-table"><div class="admin-row user-admin-head"><strong>Name</strong><strong>Email</strong><strong>Validated</strong><strong>Last login</strong><strong>Status</strong><strong>Actions</strong></div><?php foreach($allUsers as $x):$isBanned=!empty($x['banned_at']);$isDisabled=!empty($x['disabled_at']);?><div class="admin-row"><span><strong><?=e($x['display_name'])?></strong><small>Joined <?=e($x['created_at'])?></small></span><span><?=e($x['email'])?></span><span><?=$x['email_verified_at']?'<span class="badge">Yes</span>':'<span class="muted">No</span>'?></span><span><?=e($x['last_login_at']?:'Never')?></span><span><?php if($isBanned):?><span class="badge danger-badge">Banned</span><?php elseif($isDisabled):?><span class="badge muted">Disabled</span><?php else:?><span class="badge">Active</span><?php endif;?><?php if($x['is_admin']):?><small>Administrator</small><?php endif;?></span><span class="user-admin-actions"><?php if($x['is_admin']):?><span class="muted">Protected</span><?php else:?><form method="post"><input type="hidden" name="user_id" value="<?=$x['id']?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php if($isBanned):?><button class="button secondary tiny" name="action" value="user_unban">Remove ban</button><?php else:?><button class="button danger tiny" name="action" value="user_ban" onclick="return confirm('Ban this user and block this email from registration?')">Ban</button><?php endif;?><?php if(!$isBanned&&$isDisabled):?><button class="button secondary tiny" name="action" value="user_enable">Enable</button><?php elseif(!$isBanned):?><button class="button secondary tiny" name="action" value="user_disable">Disable</button><?php endif;?></form><?php endif;?></span></div><?php if($isBanned&&$x['ban_reason']):?><div class="user-ban-reason"><strong>Ban reason:</strong> <?=e($x['ban_reason'])?></div><?php endif;?><?php endforeach;?></div></section><?php endif;?>
<?php if($section==='admins'):?><div class="section-title"><div><span class="kicker">SECURITY</span><h1>Admin Access</h1></div><span>OTP default · password fallback available</span></div><div class="admin-two-col"><details class="panel admin-add"><summary><span>＋ Create administrator</span><small>OTP + optional fallback password</small></summary><form class="admin-compact-form" method="post"><input name="display_name" placeholder="Display name" required><input name="email" type="email" placeholder="Email" required><input name="password" type="password" minlength="12" autocomplete="new-password" placeholder="Optional fallback password (12+ chars)"><small class="muted">OTP remains the normal sign-in method. A password is only accepted for administrator accounts.</small><input type="hidden" name="action" value="admin_create"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button">Create admin</button></form></details><details class="panel admin-add"><summary><span>＋ Grant access</span><small>Promote an existing user</small></summary><form class="admin-compact-form" method="post"><select name="user_id" required><option value="">Choose user</option><?php foreach($nonAdmins as $x):?><option value="<?=$x['id']?>"><?=e($x['display_name'].' — '.$x['email'])?></option><?php endforeach;?></select><input type="hidden" name="action" value="admin_grant"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button">Grant access</button></form></details></div><section class="panel admin-list-panel"><div class="admin-table admin-password-table"><?php foreach($admins as $a):?><div class="admin-row admin-security-row"><span><strong><?=e($a['display_name'])?></strong><small><?=e($a['email'])?></small></span><span>Since <?=e(substr($a['created_at'],0,10))?></span><details class="admin-password-set"><summary class="button secondary tiny">Set fallback password</summary><form method="post" data-no-async><input type="hidden" name="id" value="<?=$a['id']?>"><input name="password" type="password" minlength="12" autocomplete="new-password" placeholder="New password" required><input name="password_confirm" type="password" minlength="12" autocomplete="new-password" placeholder="Confirm password" required><input type="hidden" name="action" value="admin_password_set"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button tiny">Save password</button></form></details><?php if((int)$a['id']===(int)$u['id']):?><span class="badge">YOU</span><?php else:?><form method="post"><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="action" value="admin_revoke"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button danger tiny">Remove</button></form><?php endif;?></div><?php endforeach;?></div></section><?php endif;?>


<?php if($section==='payouts'):$payoutMonth=(string)($_GET['month']??date('Y-m',strtotime('first day of last month')));if(!preg_match('/^\d{4}-\d{2}$/',$payoutMonth))$payoutMonth=date('Y-m',strtotime('first day of last month'));$periodStart=$payoutMonth.'-01';$periodEnd=date('Y-m-t',strtotime($periodStart));$payoutArtists=$pdo->query('SELECT id,name,paypal_email FROM artists ORDER BY name')->fetchAll();?><div class="section-title"><div><span class="kicker">ARTIST ACCOUNTING</span><h1>Artist Payouts</h1></div><span><?=e($payoutMonth)?> calendar month</span></div><p class="panel muted">Choose a calendar month to calculate each artist’s unpaid balance. The host charge is deducted first, then the remainder is shared between credited artists. Marking a row paid records every sale allocation so it cannot be paid twice and emails the artist a reconciliation.</p><form method="get" class="panel admin-compact-form cols"><input type="hidden" name="section" value="payouts"><label>Calendar month<input type="month" name="month" value="<?=e($payoutMonth)?>" onchange="this.form.submit()"><small>Only paid sales in this month are included.</small></label><label>Host charge (%)<input name="payout_host_percent" type="number" min="0" max="100" step="0.01" value="<?=e(number_format(payout_host_percent(),2,'.',''))?>" disabled><small>Change this with the Save payout settings action.</small></label><button class="button" type="button" onclick="document.getElementById('payout-settings-form').submit()">Save payout settings</button></form><form id="payout-settings-form" method="post"><input type="hidden" name="action" value="payout_settings"><input type="hidden" name="payout_host_percent" value="<?=e(number_format(payout_host_percent(),2,'.',''))?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"></form><section class="panel admin-list-panel"><div class="admin-section-head"><h2>Payouts by artist</h2><span><?=e($periodStart)?> to <?=e($periodEnd)?></span></div><div class="admin-table payout-table"><div class="admin-row user-admin-head"><strong>Artist</strong><strong>PayPal address</strong><strong>Gross</strong><strong>Host fee</strong><strong>Amount to pay</strong><strong>Action</strong></div><?php foreach($payoutArtists as $pa):$due=payout_items_for_artist((int)$pa['id'],$periodStart,$periodEnd);?><div class="admin-row"><span><strong><?=e($pa['name'])?></strong></span><span><?=!empty($pa['paypal_email'])?e($pa['paypal_email']):'<span class="muted">Not supplied</span>'?></span><span><?=money((int)$due['gross_pence'])?></span><span><?=money((int)$due['host_fee_pence'])?></span><span><strong><?=money((int)$due['payout_pence'])?></strong></span><span><?php if((int)$due['payout_pence']>0&&filter_var((string)$pa['paypal_email'],FILTER_VALIDATE_EMAIL)):?><form method="post" data-no-async><input type="hidden" name="action" value="payout_mark_paid"><input type="hidden" name="artist_id" value="<?=$pa['id']?>"><input type="hidden" name="period_start" value="<?=e($periodStart)?>"><input type="hidden" name="period_end" value="<?=e($periodEnd)?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button tiny" onclick="return confirm('Mark this payout as paid and email the artist?')">Mark as paid</button></form><?php else:?><span class="muted">No payout</span><?php endif;?></span></div><?php endforeach;?></div></section><section class="panel"><div class="section-title compact"><div><span class="kicker">PAYPAL REQUIREMENTS</span><h2>Before marking paid</h2></div></div><p class="muted">Mark as paid after sending the money from the configured PayPal account. This screen records the accounting allocation and emails the artist; it does not transfer money through PayPal automatically.</p></section><?php endif;?>
<?php if($section==='payouts'):$history=$pdo->query("SELECT p.*,a.name artist_name FROM artist_payouts p JOIN artists a ON a.id=p.artist_id ORDER BY p.created_at DESC,p.id DESC LIMIT 50")->fetchAll();?><section class="panel admin-list-panel"><div class="admin-section-head"><h2>Recent payout history</h2><span>Latest 50</span></div><div class="admin-table payout-history"><div class="admin-row user-admin-head"><strong>Artist</strong><strong>Period</strong><strong>Amount</strong><strong>PayPal batch</strong><strong>Status</strong></div><?php foreach($history as $hp):?><div class="admin-row"><span><?=e($hp['artist_name'])?></span><span><?=e($hp['period_start'])?> → <?=e($hp['period_end'])?></span><span><?=money((int)$hp['payout_pence'])?></span><span><?=e($hp['paypal_batch_id']?:'—')?></span><span class="badge <?=e($hp['status'])?>"><?=e(ucfirst($hp['status']))?><?php if($hp['error_message']):?><small><?=e($hp['error_message'])?></small><?php endif;?></span></div><?php endforeach;?></div></section><?php endif;?><script><?php if($section==='payouts'):?>document.querySelectorAll('form[id^="payout-period-form-"]').forEach(function(form){form.addEventListener('submit',function(){var start=document.querySelector('input[name="period_start"][form="payout-period-form"]'),end=document.querySelector('input[name="period_end"][form="payout-period-form"]');if(start)form.querySelector('input[name="period_start"]').value=start.value;if(end)form.querySelector('input[name="period_end"]').value=end.value;});});<?php endif;?></script>
<?php if($section==='payouts'):?><section class="panel admin-list-panel"><div class="admin-section-head"><h2>Automatic payout safety</h2><span>Disabled by default</span></div><form method="post" class="admin-compact-form cols"><label>Host charge (%)<input name="payout_host_percent" type="number" min="0" max="100" step="0.01" value="<?=e(number_format(payout_host_percent(),2,'.',''))?>"><small>Deducted before artist shares are calculated.</small></label><label class="check"><input type="checkbox" name="payout_paypal_confirmed" value="1" <?=payout_paypal_confirmed()?'checked':''?>> I confirm this is a PayPal Business account with PayPal Payouts enabled.</label><label class="check"><input type="checkbox" name="payout_automatic_enabled" value="1" <?=payout_automatic_enabled()?'checked':''?>> Enable automatic PayPal payouts.</label><input type="hidden" name="action" value="payout_settings"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button">Save payout settings</button></form><p class="muted">Automatic payouts are only available when PayPal is the selected payment gateway and the confirmation above is enabled. Manual marking remains available.</p></section><?php endif;?>
<?php if($section==='payouts'):?><script>(function(){var input=document.querySelector('input[type="month"][name="month"]');if(!input)return;var value=input.value.split('-'),wrap=document.createElement('span');wrap.className='payout-month-selects';var month=document.createElement('select'),year=document.createElement('select');month.setAttribute('aria-label','Month');year.setAttribute('aria-label','Year');['January','February','March','April','May','June','July','August','September','October','November','December'].forEach(function(name,i){var o=new Option(name,String(i+1).padStart(2,'0'),String(i+1).padStart(2,'0')===value[1]);month.add(o);});var current=new Date().getFullYear();for(var y=current;y>=current-3;y--){var o=new Option(String(y),String(y),String(y)===value[0]);year.add(o);}function change(){input.value=year.value+'-'+month.value;input.form.submit();}month.addEventListener('change',change);year.addEventListener('change',change);wrap.append(month,year);input.replaceWith(wrap);})();</script><?php endif;?>
<?php if($section==='payouts'):?><script>document.querySelectorAll('.payout-month-selects').forEach(function(w){var form=w.closest('form'),hidden=document.createElement('input');hidden.type='hidden';hidden.name='month';function sync(){hidden.value=w.querySelector('select[aria-label="Year"]').value+'-'+w.querySelector('select[aria-label="Month"]').value;}sync();form.append(hidden);w.addEventListener('change',sync);});</script><?php endif;?>
<?php if($section==='payouts'):?><script>(function(){var view=<?=json_encode($payoutView)?>,workspace=document.querySelector('.admin-workspace');if(!workspace)return;var children=Array.from(workspace.children).filter(function(el){return !el.matches('script')&&!el.classList.contains('admin-flash');});function find(text){return children.find(function(el){return (el.textContent||'').indexOf(text)!==-1;});}var title=children.find(function(el){return el.querySelector&&el.querySelector('h1')&&el.textContent.indexOf('Artist Payouts')!==-1;}),intro=children.find(function(el){return el.tagName==='P'&&el.classList.contains('panel');}),month=children.find(function(el){return el.querySelector&&el.querySelector('input[name="month"]');}),report=find('Payouts by artist'),requirements=find('Before marking paid'),history=find('Recent payout history'),settings=find('Automatic payout safety');var keep=view==='settings'?[settings]:view==='history'?[history]:[title,intro,month,report,requirements];children.forEach(function(el){if(keep.indexOf(el)===-1)el.hidden=true;});})();</script><?php endif;?>
