ction><?php endif;?><?php if($section==='audit'):$auditRows=[];try{$auditRows=$pdo->query("SELECT l.id,l.event_type,l.user_agent,l.metadata_json,l.created_at,u.display_name,u.email,INET6_NTOA(l.ip_address) ip_address_text FROM audit_log l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC,l.id DESC LIMIT 500")->fetchAll();}catch(Throwable $ignored){}?><div class="section-title"><div><span class="kicker">SECURITY</span><h1>Audit Log</h1></div><span>Latest <?=count($auditRows)?> events</span></div><section class="panel admin-list-panel audit-log-panel"><div class="admin-section-head"><h2>Account and security activity</h2><span>IP address · browser agent</span></div><div class="audit-log-list"><div class="audit-log-row audit-log-head"><strong>When</strong><strong>Event</strong><strong>User</strong><strong>IP address</strong><strong>Browser agent</strong><strong>Details</strong></div><?php foreach($auditRows as $row):?><div class="audit-log-row"><span><?=e($row['created_at'])?></span><strong><?=e($row['event_type'])?></strong><span><?=e($row['display_name']?:$row['email']?:'System')?></span><span><?=e($row['ip_address_text']?:'Unknown')?></span><span class="audit-agent"><?=e($row['user_agent']?:'Unknown')?></span><span><?=e($row['metadata_json']?:'')?></span></div><?php endforeach;?><?php if(!$auditRows):?><p class="muted">No audit events are available yet.</p><?php endif;?></div></section><?php endif;?>
